import { gsap } from 'gsap';
import {
  MeshBasicNodeMaterial,
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  DoubleSide,
  Color
} from 'three/webgpu';
import { uv, color, mix, smoothstep, vec2, length as tslLength } from 'three/tsl';

function buildGradient(coord, stops) {
  let node = color(stops[0].hex);
  for (let i = 1; i < stops.length; i++) {
    node = mix(node, color(stops[i].hex), smoothstep(stops[i - 1].at, stops[i].at, coord));
  }
  return node;
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, OctahedronGeometry, DirectionalLight } = THREE;

  const visual = config.intent?.visualSpec ?? {};
  const colors = visual.colors ?? config.colors ?? {};
  const gradientStops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.6, hex: '#12121a' },
    { at: 1, hex: '#16161d' }
  ];
  const accent = colors.accent ?? '#ff2a38';
  const paper = colors.paper ?? '#e8ecf2';
  const ink = colors.ink ?? '#16161d';
  const coolRim = '#9fb0c4';

  const root = new Group();
  const disposables = [];
  const timelines = [];
  const primitiveResults = [];

  // ---------------------------------------------------------------
  // BACKDROP — 7x6 plane at z=-2.5 carrying the vertical gradient
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = buildGradient(uv().y, gradientStops);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // PRISM — equilateral triangular cross section, dispersive glass
  // ---------------------------------------------------------------
  const sideLen = 1.2;
  const prismRadius = sideLen / Math.sqrt(3);
  const prismLength = 1.8;
  const prismGeo = new CylinderGeometry(prismRadius, prismRadius, prismLength, 3, 1, false);
  // orient default vertical (Y) axis cylinder so its length runs horizontal (X)
  prismGeo.rotateZ(Math.PI / 2);

  const prismMat = new MeshPhysicalNodeMaterial();
  prismMat.color = new Color(paper);
  prismMat.transmission = 1.0;
  prismMat.thickness = 0.9;
  prismMat.ior = 1.55;
  prismMat.roughness = 0.08;
  prismMat.metalness = 0.0;
  prismMat.clearcoat = 0.25;
  prismMat.clearcoatRoughness = 0.1;
  prismMat.iridescence = 1.0;
  prismMat.iridescenceIOR = 1.3;
  prismMat.iridescenceThicknessRange = [120, 480];
  prismMat.attenuationColor = new Color(paper);
  prismMat.attenuationDistance = 2.5;
  prismMat.dispersion = 0.18;
  prismMat.side = DoubleSide;

  const prismGroup = new Group();
  const prismMesh = new Mesh(prismGeo, prismMat);
  prismGroup.add(prismMesh);
  // base tilt per spec: 12deg z, 20deg y
  prismGroup.rotation.set(0, THREE.MathUtils.degToRad(20), THREE.MathUtils.degToRad(12));
  root.add(prismGroup);
  disposables.push(prismGeo, prismMat);

  // ---------------------------------------------------------------
  // EMISSIVE CORE — octahedron inside prism
  // ---------------------------------------------------------------
  const coreGeo = new OctahedronGeometry(0.35);
  const coreMat = new MeshStandardNodeMaterial();
  coreMat.color = new Color(accent);
  coreMat.emissive = new Color(accent);
  coreMat.emissiveIntensity = 2.2;
  coreMat.roughness = 0.4;
  coreMat.metalness = 0.1;
  const core = new Mesh(coreGeo, coreMat);
  prismGroup.add(core);
  disposables.push(coreGeo, coreMat);

  // ---------------------------------------------------------------
  // BACK RIM LIGHT — cool directional from behind-left
  // ---------------------------------------------------------------
  const rimLight = new DirectionalLight(new Color(coolRim), 0.9);
  rimLight.position.set(-3.2, 1.4, -2.6);
  root.add(rimLight);
  if (rimLight.target) {
    rimLight.target.position.set(0, 0, 0);
    root.add(rimLight.target);
  }

  // ---------------------------------------------------------------
  // CAUSTIC STREAK — floor plane with dispersed gradient
  // ---------------------------------------------------------------
  const causticStops = [
    { at: 0.2, hex: accent },
    { at: 0.5, hex: paper },
    { at: 0.8, hex: coolRim }
  ];
  const causticGeo = new PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshBasicNodeMaterial();
  causticMat.colorNode = buildGradient(uv().x, causticStops);
  const edgeFade = smoothstep(0.0, 0.12, uv().x).mul(smoothstep(1.0, 0.88, uv().x));
  causticMat.opacityNode = edgeFade.mul(0.35);
  causticMat.transparent = true;
  causticMat.depthWrite = false;
  const caustic = new Mesh(causticGeo, causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.set(0, -1.1, -0.2);
  root.add(caustic);
  disposables.push(causticGeo, causticMat);

  // ---------------------------------------------------------------
  // CONTACT SHADOW — radial gradient plane under the prism
  // ---------------------------------------------------------------
  const shadowRadius = sideLen * 1.35;
  const shadowGeo = new PlaneGeometry(shadowRadius * 2, shadowRadius * 2);
  const shadowMat = new MeshBasicNodeMaterial();
  const centered = uv().sub(vec2(0.5, 0.5));
  const dist = tslLength(centered).mul(2.0);
  shadowMat.colorNode = color(ink);
  shadowMat.opacityNode = smoothstep(1.0, 0.0, dist).mul(0.5);
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.set(0, -1.12, 0);
  root.add(shadowPlane);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------
  // TEXT — headline + caption from spec copy
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const typography = visual.typography ?? {};

  for (const item of items) {
    const isHeadline = item.role === 'headline';
    const opts = isHeadline
      ? {
          fontSize: item.typography?.fontSize ?? typography.headline?.fontSize ?? 68,
          color: paper,
          align: 'center'
        }
      : {
          fontSize: item.typography?.fontSize ?? typography.caption?.fontSize ?? 18,
          color: coolRim,
          align: 'center',
          letterSpacingPx: 1.4
        };
    const textObj = ctx.fontAtlas.createText(item.text, opts);
    textObj.position.set(0, isHeadline ? -1.75 : -2.25, 0.05);
    root.add(textObj);
  }

  // ---------------------------------------------------------------
  // MOTION — idle breathing (subject weight) + hover depth-rotate
  // ---------------------------------------------------------------
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(prismGroup.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 2.4,
    ease: 'sine.inOut'
  });
  timelines.push(idleTl);

  const settleTl = gsap.timeline();
  prismGroup.scale.set(0.96, 0.96, 0.96);
  settleTl.to(prismGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  });
  timelines.push(settleTl);

  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const primitive of primitiveConfigs) {
    const applyFn = ctx.primitives?.[primitive.name];
    if (typeof applyFn === 'function') {
      const result = applyFn(prismGroup, { ...primitive.params, trigger: primitive.trigger });
      if (result) primitiveResults.push(result);
    }
  }

  // ---------------------------------------------------------------
  // HANDLERS
  // ---------------------------------------------------------------
  root.userData.handlers = {
    onPointerOver: () => {
      gsap.to(coreMat, { emissiveIntensity: 2.3, duration: 0.3, ease: 'power2.out' });
    },
    onPointerOut: () => {
      gsap.to(coreMat, { emissiveIntensity: 2.2, duration: 0.3, ease: 'power2.out' });
    }
  };

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const res of primitiveResults) {
      if (res && typeof res.cleanup === 'function') res.cleanup();
    }
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    if (rimLight.target && rimLight.target.parent) rimLight.target.parent.remove(rimLight.target);
    if (rimLight.parent) rimLight.parent.remove(rimLight);
  };

  return root;
}
